import React, { useState, useEffect, useRef, useCallback } from 'react';
import EventList from './components/EventList';
import BookingModal from './components/BookingModal';
import CreateEventForm from './components/CreateEventForm';
import BookingList from './components/BookingList';
import { getAllEvents, bookEvent, cancelBooking, createEvent, getAllBookings, WS_URL } from './api/eventsApi';

/* ── Global styles injected once ─────────────────────────────────────── */
const GLOBAL_CSS = `
  @import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@300;400;500;600&family=DM+Mono:wght@400;500&display=swap');

  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

  :root {
    --bg:        #0f1117;
    --surface:   #181c27;
    --surface2:  #1e2336;
    --border:    #2a3050;
    --accent:    #4f7cff;
    --accent2:   #7c3aed;
    --success:   #22c55e;
    --danger:    #ef4444;
    --warn:      #f59e0b;
    --text:      #e8ecf4;
    --muted:     #7a84a0;
    --radius:    10px;
    --font:      'DM Sans', sans-serif;
    --mono:      'DM Mono', monospace;
  }

  body {
    background: var(--bg);
    color: var(--text);
    font-family: var(--font);
    font-size: 14px;
    line-height: 1.6;
    min-height: 100vh;
  }

  /* Scrollbar */
  ::-webkit-scrollbar { width: 6px; }
  ::-webkit-scrollbar-track { background: var(--bg); }
  ::-webkit-scrollbar-thumb { background: var(--border); border-radius: 3px; }

  /* Table base */
  table { width: 100%; border-collapse: collapse; }
  th {
    font-size: 11px; font-weight: 600; letter-spacing: .08em;
    text-transform: uppercase; color: var(--muted);
    padding: 10px 14px; background: var(--surface2);
    border-bottom: 1px solid var(--border); text-align: left;
  }
  td {
    padding: 12px 14px;
    border-bottom: 1px solid var(--border);
    color: var(--text);
    vertical-align: middle;
  }
  tbody tr:last-child td { border-bottom: none; }
  tbody tr:hover { background: rgba(79,124,255,.05); transition: background .15s; }

  /* Inputs */
  input, textarea, select {
    background: var(--surface2);
    border: 1px solid var(--border);
    border-radius: 6px;
    color: var(--text);
    font-family: var(--font);
    font-size: 14px;
    padding: 8px 12px;
    outline: none;
    transition: border-color .2s, box-shadow .2s;
    width: 100%;
  }
  input:focus, textarea:focus, select:focus {
    border-color: var(--accent);
    box-shadow: 0 0 0 3px rgba(79,124,255,.15);
  }
  input::placeholder, textarea::placeholder { color: var(--muted); }
  select option { background: var(--surface2); }
  input[type="datetime-local"]::-webkit-calendar-picker-indicator { filter: invert(.5); cursor: pointer; }

  label {
    display: block; font-size: 12px; font-weight: 500;
    color: var(--muted); margin-bottom: 5px; letter-spacing: .04em;
  }

  /* Buttons */
  .btn {
    display: inline-flex; align-items: center; gap: 6px;
    padding: 8px 16px; border-radius: 6px; border: none;
    font-family: var(--font); font-size: 13px; font-weight: 500;
    cursor: pointer; transition: all .18s; white-space: nowrap;
  }
  .btn-primary { background: var(--accent); color: #fff; }
  .btn-primary:hover { background: #3d6aff; box-shadow: 0 0 16px rgba(79,124,255,.35); }
  .btn-danger  { background: var(--danger); color: #fff; }
  .btn-danger:hover  { background: #dc2626; }
  .btn-ghost   { background: transparent; color: var(--muted); border: 1px solid var(--border); }
  .btn-ghost:hover   { color: var(--text); border-color: var(--accent); }
  .btn:disabled { opacity: .4; cursor: not-allowed; }

  /* Badge */
  .badge {
    display: inline-flex; align-items: center; justify-content: center;
    padding: 2px 9px; border-radius: 20px;
    font-size: 11px; font-weight: 600; letter-spacing: .04em;
  }
  .badge-success { background: rgba(34,197,94,.15);  color: var(--success); }
  .badge-danger  { background: rgba(239,68,68,.15);  color: var(--danger);  }
  .badge-neutral { background: rgba(122,132,160,.15); color: var(--muted);   }

  /* Card */
  .card {
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: var(--radius);
    overflow: hidden;
  }

  /* Section header */
  .section-header {
    display: flex; align-items: center; justify-content: space-between;
    padding: 16px 20px; border-bottom: 1px solid var(--border);
  }
  .section-title {
    font-size: 13px; font-weight: 600; letter-spacing: .06em;
    text-transform: uppercase; color: var(--muted);
  }

  /* Toast */
  .toast {
    position: fixed; bottom: 24px; right: 24px;
    padding: 12px 18px; border-radius: 8px;
    font-size: 13px; font-weight: 500;
    box-shadow: 0 8px 32px rgba(0,0,0,.4);
    animation: slideUp .25s ease;
    z-index: 9999; max-width: 340px;
  }
  .toast-success { background: #14532d; border: 1px solid #166534; color: #bbf7d0; }
  .toast-error   { background: #450a0a; border: 1px solid #7f1d1d; color: #fecaca; }
  @keyframes slideUp {
    from { transform: translateY(20px); opacity: 0; }
    to   { transform: translateY(0);    opacity: 1; }
  }

  /* Seat bar */
  .seat-bar-wrap { display: flex; align-items: center; gap: 8px; }
  .seat-bar-bg { flex: 1; height: 5px; background: var(--border); border-radius: 3px; overflow: hidden; }
  .seat-bar-fill { height: 100%; border-radius: 3px; transition: width .4s ease; }

  /* Scrollable table wrapper */
  .table-scroll { overflow-x: auto; }
`;

function App() {
  const [events, setEvents]               = useState([]);
  const [bookings, setBookings]           = useState([]);
  const [selectedEvent, setSelectedEvent] = useState(null);
  const [loading, setLoading]             = useState(false);
  const [message, setMessage]             = useState(null);
  const [error, setError]                 = useState(null);
  const [wsStatus, setWsStatus]           = useState('connecting');
  const wsRef = useRef(null);

  /* Inject global CSS once */
  useEffect(() => {
    const style = document.createElement('style');
    style.textContent = GLOBAL_CSS;
    document.head.appendChild(style);
    return () => document.head.removeChild(style);
  }, []);

  const showMessage = (msg, isError = false) => {
    if (isError) { setError(msg); setMessage(null); }
    else          { setMessage(msg); setError(null); }
    setTimeout(() => { setMessage(null); setError(null); }, 5000);
  };

  const fetchAll = useCallback(async () => {
    try {
      const [eventsRes, bookingsRes] = await Promise.all([getAllEvents(), getAllBookings()]);
      setEvents(eventsRes.data);
      const enriched = bookingsRes.data.map((b) => ({
        ...b,
        eventName: eventsRes.data.find((e) => e.id === b.event_id)?.name || `Event #${b.event_id}`,
      }));
      setBookings(enriched);
    } catch (err) {
      showMessage(`Failed to load data: ${err.message}`, true);
    }
  }, []);

  const connectWebSocket = useCallback(() => {
    if (wsRef.current && wsRef.current.readyState === WebSocket.OPEN) return;
    const ws = new WebSocket(WS_URL);
    wsRef.current = ws;
    ws.onopen  = () => setWsStatus('open');
    ws.onmessage = (event) => {
      try {
        const data = JSON.parse(event.data);
        if (data.type === 'seat_update') {
          setEvents((prev) => prev.map((e) =>
            e.id === data.event_id ? { ...e, available_seats: data.available_seats } : e
          ));
        }
      } catch (_) {}
    };
    ws.onclose = () => {
      setWsStatus('closed');
      setTimeout(() => { setWsStatus('connecting'); connectWebSocket(); }, 3000);
    };
    ws.onerror = () => ws.close();
  }, []);

  useEffect(() => {
    const init = async () => { setLoading(true); await fetchAll(); setLoading(false); };
    init();
    connectWebSocket();
    return () => { if (wsRef.current) wsRef.current.close(); };
  }, [fetchAll, connectWebSocket]);

  const handleBook = (event) => setSelectedEvent(event);

  const handleConfirmBooking = async (eventId, userName) => {
    setSelectedEvent(null);
    try {
      await bookEvent(eventId, userName);
      const bookingsRes = await getAllBookings();
      setBookings(bookingsRes.data.map((b) => ({
        ...b,
        eventName: events.find((e) => e.id === b.event_id)?.name || `Event #${b.event_id}`,
      })));
      showMessage('Booking confirmed successfully.');
    } catch (err) {
      showMessage(`Booking failed: ${err.message}`, true);
    }
  };

  const handleCancelBooking = async (bookingId) => {
    if (!window.confirm('Cancel this booking?')) return;
    try {
      await cancelBooking(bookingId);
      const bookingsRes = await getAllBookings();
      setBookings(bookingsRes.data.map((b) => ({
        ...b,
        eventName: events.find((e) => e.id === b.event_id)?.name || `Event #${b.event_id}`,
      })));
      showMessage(`Booking #${bookingId} cancelled. Seat restored.`);
    } catch (err) {
      showMessage(`Cancel failed: ${err.message}`, true);
    }
  };

  const handleCreateEvent = async (eventData) => {
    try {
      await createEvent(eventData);
      showMessage(`Event "${eventData.name}" created successfully.`);
      await fetchAll();
    } catch (err) {
      showMessage(`Failed to create event: ${err.message}`, true);
    }
  };

  const wsInfo = {
    open:       { color: '#22c55e', dot: '#22c55e', label: 'Live' },
    connecting: { color: '#f59e0b', dot: '#f59e0b', label: 'Connecting' },
    closed:     { color: '#ef4444', dot: '#ef4444', label: 'Disconnected' },
  }[wsStatus];

  return (
    <div style={{ maxWidth: 1140, margin: '0 auto', padding: '28px 24px 60px' }}>

      {/* ── Header ── */}
      <header style={{
        display: 'flex', alignItems: 'center', justifyContent: 'space-between',
        marginBottom: 32, paddingBottom: 20,
        borderBottom: '1px solid var(--border)',
      }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
          <div style={{
            width: 36, height: 36, borderRadius: 8,
            background: 'linear-gradient(135deg, var(--accent), var(--accent2))',
            display: 'flex', alignItems: 'center', justifyContent: 'center',
            fontSize: 18,
          }}>🎟</div>
          <div>
            <div style={{ fontSize: 18, fontWeight: 600, letterSpacing: '-.01em', color: 'var(--text)' }}>
              Event Booking
            </div>
            <div style={{ fontSize: 11, color: 'var(--muted)', letterSpacing: '.04em' }}>
              MANAGEMENT SYSTEM
            </div>
          </div>
        </div>

        {/* WS status pill */}
        <div style={{
          display: 'flex', alignItems: 'center', gap: 7,
          padding: '5px 12px', borderRadius: 20,
          background: 'var(--surface)', border: '1px solid var(--border)',
          fontSize: 12, fontWeight: 500, color: wsInfo.color,
        }}>
          <span style={{
            width: 7, height: 7, borderRadius: '50%',
            background: wsInfo.dot,
            boxShadow: wsStatus === 'open' ? `0 0 6px ${wsInfo.dot}` : 'none',
            animation: wsStatus === 'open' ? 'none' : undefined,
          }} />
          {wsInfo.label}
        </div>
      </header>

      {/* ── Toasts ── */}
      {message && <div className="toast toast-success">{message}</div>}
      {error   && <div className="toast toast-error">{error}</div>}

      {/* ── Sections ── */}
      <div style={{ display: 'flex', flexDirection: 'column', gap: 28 }}>
        <EventList  events={events} onBook={handleBook} onRefresh={fetchAll} loading={loading} />
        <BookingList bookings={bookings} onCancel={handleCancelBooking} />
        <CreateEventForm onCreateEvent={handleCreateEvent} />
      </div>

      {selectedEvent && (
        <BookingModal event={selectedEvent} onConfirm={handleConfirmBooking} onClose={() => setSelectedEvent(null)} />
      )}
    </div>
  );
}

export default App;
